import{_ as t,o as a,c as s,a2 as d}from"./chunks/framework.Bg-Zxr5O.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/SELECT-IF.md","filePath":"manual-en/SELECT-IF.md","lastUpdated":1785684581000}'),o={name:"manual-en/SELECT-IF.md"};function r(n,e,i,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[d(`<h3 id="_13-4-select-if" tabindex="-1">13.4 SELECT IF <a class="header-anchor" href="#_13-4-select-if" aria-label="Permalink to &quot;13.4 SELECT IF&quot;">​</a></h3><pre><code>SELECT IF expression.
</code></pre><p><code>SELECT IF</code> selects cases for analysis based on the value of expression. Cases not selected are permanently eliminated from the active dataset, unless <code>TEMPORARY</code> is in effect (see <a href="./TEMPORARY">TEMPORARY</a>).</p><p>Specify a boolean expression (see <a href="./Expressions">Expressions</a>). If the value of the expression is true for a particular case, the case is analyzed. If the expression has a false or missing value, then the case is deleted from the data stream.</p><p>Place <code>SELECT IF</code> as early in the command file as possible. Cases that are deleted early can be processed more efficiently in time and space. Once cases have been deleted from the active dataset using <code>SELECT IF</code> they cannot be re-instated. If you want to be able to re-instate cases, then use <code>FILTER</code> (see <a href="./FILTER">FILTER</a>) instead.</p><p>When <code>SELECT IF</code> is specified following <code>TEMPORARY</code> (see <a href="./TEMPORARY">TEMPORARY</a>), the <code>LAG</code> function may not be used (see <a href="./Miscellaneous-Functions#LAG">LAG</a>).</p><h4 id="_13-4-1-example-select-if" tabindex="-1">13.4.1 Example Select-If <a class="header-anchor" href="#_13-4-1-example-select-if" aria-label="Permalink to &quot;13.4.1 Example Select-If&quot;">​</a></h4><p>A shop steward is interested in the salaries of younger personnel in a firm. The file personnel.sav provides the salaries of all the workers and their dates of birth. The syntax in Example 13.1 shows how <code>SELECT IF</code> can be used to limit analysis only to those persons born after December 31, 1999.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file = &#39;personnel.sav&#39;.  echo &#39;Salaries of all personnel&#39;. descriptives salary.  echo &#39;Salaries of personnel born after December 31 1999&#39;. select if dob &gt; date.dmy (31,12,1999). descriptives salary.</span></span></code></pre></div><p><strong>Example 13.1:</strong> Using <code>SELECT IF</code> to select persons born on or after a certain date.</p><p>From Result 13.1 one can see that there are 56 persons listed in the dataset, and 17 of them were born after December 31, 1999.</p><table tabindex="0"><thead><tr><th></th><th>N</th><th>Mean</th><th>Std Dev</th><th>Minimum</th><th>Maximum</th></tr></thead><tbody><tr><td>Annual salary before tax</td><td>56</td><td>40028.97</td><td>8721.17</td><td>$23,451</td><td>$57,044</td></tr><tr><td>Valid N (listwise)</td><td>56</td><td></td><td></td><td></td><td></td></tr><tr><td>Missing N (listwise)</td><td>0</td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>N</td><td>Mean</td><td>Std Dev</td><td>Minimum</td><td>Maximum</td></tr><tr><td>Annual salary before tax</td><td>17</td><td>31828.59</td><td>4454.80</td><td>$23,451</td><td>$39,504</td></tr><tr><td>Valid N (listwise)</td><td>17</td><td></td><td></td><td></td><td></td></tr><tr><td>Missing N (listwise)</td><td>0</td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Result 13.1:</strong> Salary descriptives before and after the <code>SELECT IF</code> transformation.</p><p>Note that the personnel.sav file from which the data were read is unaffected. The transformation affects only the active file.</p>`,14)])])}const m=t(o,[["render",r]]);export{f as __pageData,m as default};
